package com.nexttenant.seo;

import java.util.List;

/**
 * The rent ceilings that get a page of their own.
 *
 * <h2>Why a fixed list and not any number</h2>
 *
 * <p>{@code /flats-in-powai-under-{budget}} with an open-ended budget is an
 * infinite URL space over a finite set of listings: {@code -under-25000},
 * {@code -under-25001}, {@code -under-25002}, each a page that answers 200 with
 * nearly the same content. A crawler will find them — they are generated by
 * nothing more than an incrementing number in a link somebody wrote — and
 * spend its budget on permutations instead of on the listings. Google's
 * guidance on this is blunt, and the penalty for "scaled content" lands on the
 * whole domain rather than the thin pages.
 *
 * <p>So the set of valid budgets is this list, and everything else is a 404.
 * Nine pages per area that each mean something, rather than fifty thousand
 * that do not.
 *
 * <h2>Why these nine numbers</h2>
 *
 * <p>They are the round figures people actually type and say — "under 25k",
 * "under 40" — not an even split of the rent distribution. The point of the
 * page is to match a search query, and nobody searches for rooms under
 * ₹27,350.
 *
 * <h2>Why a constant and not a table</h2>
 *
 * <p>These are a product decision about which searches are worth a page, not
 * data about Mumbai. Changing them changes the URL space, which is a change
 * that should arrive as a reviewed commit and a redeploy — not as an UPDATE
 * somebody ran on a Friday that silently 404s a page Google has indexed.
 */
public final class Budgets {

    /** Ascending, because the page offers them to a reader in this order. */
    public static final List<Integer> ALLOWED =
            List.of(10_000, 15_000, 20_000, 25_000, 30_000, 40_000, 50_000, 75_000, 100_000);

    private Budgets() {
    }

    /** True for a budget that has a page. */
    public static boolean isAllowed(int budget) {
        return ALLOWED.contains(budget);
    }

    /**
     * "₹25,000" as it appears in a title and a heading.
     *
     * <p>Not {@link com.nexttenant.common.Rupees}, which formats for the UI and
     * may well start abbreviating to "25k". A title tag and a URL should agree
     * on the number, and a title that says 25k against a URL that says 25000 is
     * a small inconsistency a reader notices in a search result.
     */
    public static String format(int budget) {
        return "₹" + String.format("%,d", budget);
    }
}
